"""An ended session, as the threads the agent saw while it played it.

The arena returns a finished session as a trace of moves (`client.session(id)`, the files under
`analysis/pegasus_data/sessions/`); the agent reads threads of e-mails. `threads_of` turns the
first into the second, so a decision can be inspected or a state rebuilt on real transcripts.

A replay can check what we would decide in a situation that happened. It cannot tell how the
supplier would have answered an offer that was never sent.
"""

import json
from pathlib import Path


def supplier_message(move):
    """A supplier move of the trace as the e-mail the agent received."""
    sheets = []
    if move.get("offer_id") and (move.get("terms") or {}).get("unit_price") is not None:
        sheets.append({"term_sheet_id": move["offer_id"], "terms": dict(move["terms"])})
    for alt in move.get("alternatives") or []:
        if alt.get("offer_id") and alt.get("terms"):
            sheets.append({"term_sheet_id": alt["offer_id"], "terms": dict(alt["terms"])})
    return {"from": "supplier", "status": move.get("status") or "open", "body": move.get("text") or "",
            "term_sheets": sheets, "attachments": [], "missing_fields": list(move.get("missing_fields") or []),
            "claim_results": list(move.get("claim_results") or [])}


def buyer_message(move):
    """One of our moves of the trace as the message we sent."""
    if move.get("type") in ("accept", "walk_away"):
        action = {"type": move["type"]}
        if move.get("offer_id"):
            action["term_sheet_id"] = move["offer_id"]
        return {"from": "buyer", "action": action}
    out = {"from": "buyer", "subject": move.get("subject") or "", "body": move.get("body") or "",
           "term_sheets": [{"terms": dict(ts.get("terms", ts))} for ts in move.get("term_sheets") or []]}
    if move.get("refs"):
        out["refs"] = list(move["refs"])
    return out


def threads_of(session, upto=None):
    """{supplier_id: [message, ...]} from a session's trace. `upto`: keep only the first `upto`
    trace entries (the situation at that point of the game)."""
    trace = ((session.get("result") or {}).get("trace")) or []
    suppliers = [e["actor"] for e in trace if e.get("actor") != "buyer"]
    threads = {s: [] for s in dict.fromkeys(suppliers)}
    only = next(iter(threads), None)
    for entry in trace[:upto]:
        move = entry.get("move") or {}
        if entry.get("actor") == "buyer":
            sid = move.get("supplier_id") or only
            if sid in threads:
                threads[sid].append(buyer_message(move))
        elif entry["actor"] in threads:
            threads[entry["actor"]].append(supplier_message(move))
    return {s: ev for s, ev in threads.items() if ev}


def load(path):
    """A session file: the arena's session object, or our archive's {"summary", "session", ...}."""
    data = json.loads(Path(path).read_text(encoding="utf-8"))
    return data.get("session") or data


def openings(directory, case_id):
    """The opening threads of a case from the first archived session of it (the opening quote is
    an input of the game, not a result): {supplier_id: [opening message]}, {} when none is archived."""
    name = case_id.split(":")[-1]
    for path in sorted(Path(directory).glob(f"{name}-*.json")):
        try:
            session = load(path)
        except (OSError, ValueError):
            continue
        threads = threads_of(session)
        first = {s: ev[:1] for s, ev in threads.items() if ev and ev[0].get("from") != "buyer"}
        if first:
            return first
    return {}

"""One evaluation of a term sheet, used to propose, to compare and to conclude.

Two things of different standing, kept apart:
- `commercial`: what the sheet costs us by the published cost function (`arena_kit.cost`) -
  accounting, as exact as the case file and the supplier's standard terms;
- `risks`: the relationship charge under each hypothesis we hold about the supplier's full cost
  (strategic and bottleneck goals only) - estimates, each with where it comes from.
When the charge applies and we hold no hypothesis the risk is unknown, not zero: `known` is False
and `commercial` is then an optimistic bound. A choice that flips with the hypothesis is `fragile`:
the caller must say so instead of treating one estimate as the truth.
"""

from dataclasses import dataclass, field

from arena_kit.cost import RELATIONSHIP_GOALS, closing_terms, must_haves_ok, relationship_cost, total_cost

INF = float("inf")


@dataclass
class Evaluation:
    valid: bool  # complete, priced and within the must-haves
    commercial: float  # C by the published function, no estimate of the supplier in it
    risks: list = field(default_factory=list)  # [{"name", "eur", "provenance"}], one per hypothesis
    known: bool = True  # False: a relationship charge applies and we cannot estimate it

    @property
    def low(self):
        """Total under the most favourable hypothesis."""
        return self.commercial + min((r["eur"] for r in self.risks), default=0.0)

    @property
    def cautious(self):
        """Total under the least favourable hypothesis: what decisions are taken on."""
        return self.commercial + max((r["eur"] for r in self.risks), default=0.0)

    def summary(self):
        return {"valid": self.valid, "commercial": round(self.commercial, 2), "low": round(self.low, 2),
                "cautious": round(self.cautious, 2), "known": self.known,
                "risks": [{**r, "eur": round(r["eur"], 2)} for r in self.risks]}


def charge_applies(case):
    """The arena charges a relationship cost in this case (strategic and bottleneck goals)."""
    b = case["buyer"]
    return bool(b.get("category_goal") in RELATIONSHIP_GOALS and b.get("relationship_eur_per_point")
                and b.get("sustainable_margin_pct"))


def clean(terms):
    """Without the private keys pegasus keeps next to the supplier's standard terms."""
    return {k: v for k, v in (terms or {}).items() if not k.startswith("_")}


def evaluate(case, terms, std=None, hypotheses=()):
    """`terms`: a term sheet (the supplier's standard terms `std` fill what it leaves out).
    `hypotheses`: [{"name", "supplier", "provenance"}], `supplier` as `arena_kit.cost.supplier_value`
    takes it. Never raises: a sheet that cannot be costed is invalid at an infinite cost."""
    std, terms = clean(std), clean(terms)
    applies = charge_applies(case)
    if terms.get("unit_price") is None:
        return Evaluation(False, INF, [], not applies)
    try:
        closed = closing_terms(case, terms, std)
        commercial = total_cost(case, closed)
        valid = must_haves_ok(case, closed)
    except (KeyError, TypeError, ValueError):
        return Evaluation(False, INF, [], not applies)
    risks = []
    for h in hypotheses if applies else ():
        try:
            eur = relationship_cost(case, closed, supplier=h["supplier"])
        except (KeyError, TypeError, ValueError, ZeroDivisionError):
            continue
        risks.append({"name": h["name"], "eur": eur, "provenance": h.get("provenance", "")})
    return Evaluation(valid, commercial, risks, bool(risks) or not applies)


def better(a, b, margin=0.0):
    """`a` beats `b` on the cautious total, by more than `margin` EUR."""
    return a.valid and (not b.valid or a.cautious < b.cautious - margin)


def fragile(a, b):
    """The order of two valid sheets depends on which hypothesis about the supplier is true."""
    if not (a.valid and b.valid):
        return False
    return (a.low < b.low) != (a.cautious < b.cautious)


def best(evaluated):
    """(key, Evaluation) with the lowest cautious total among the valid ones, else None.
    `evaluated`: iterable of (key, Evaluation)."""
    valid = [(k, e) for k, e in evaluated if e.valid]
    return min(valid, key=lambda x: x[1].cautious) if valid else None

"""The run's resolved configuration, written before any session opens.

A score is only worth something if we can say which code, data, settings, memory and prompts
produced it. `record` writes `data/runs/<UTC>-<fingerprint>/config.json` and returns the run
directory; `Journal` appends one JSON line per decision next to it (`decisions.jsonl`).

No secret enters either file: a key is recorded as "set" or missing, never its value. The
fingerprint covers what changes the agent's behaviour (code, settings, data, initial memory,
reader cache, playbook, prompts) - not the clock, the command line or who validated the launch.
"""

import hashlib
import json
import logging
import os
import platform
import subprocess
import sys
import threading
import time
from pathlib import Path

log = logging.getLogger("pegasus")

ROOT = Path(__file__).resolve().parents[2]
SECRET_WORDS = ("KEY", "TOKEN", "SECRET", "PASSWORD")
ENV_PREFIXES = ("PEGASUS_", "LLM_", "ARENA_", "HOLLERAU_")
# recorded for the trace, but they do not change how the agent negotiates
NOT_BEHAVIOUR = {"HOLLERAU_VALIDATED", "ARENA_URL", "ARENA_API_KEY", "PEGASUS_RUNS", "PEGASUS_NONCE"}
SIMPLE = (bool, int, float, str, list, tuple)


def runs_dir():
    return Path(os.environ.get("PEGASUS_RUNS", "data/runs"))


def secret(name):
    return any(w in name.upper() for w in SECRET_WORDS)


def sha(path):
    """sha256 of a file, None when it does not exist."""
    p = Path(path)
    if not p.is_file():
        return None
    h = hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def tree_sha(root):
    """One hash for a directory: every file's relative path and content, in a fixed order."""
    root = Path(root)
    if not root.is_dir():
        return None, 0
    h, n = hashlib.sha256(), 0
    for p in sorted(x for x in root.rglob("*") if x.is_file()):
        h.update(str(p.relative_to(root)).encode() + b"\0" + (sha(p) or "").encode() + b"\n")
        n += 1
    return h.hexdigest(), n


def code():
    """The commit that runs, and whether tracked files differ from it."""
    def git(*args):
        try:
            r = subprocess.run(["git", "-C", str(ROOT), *args], capture_output=True, text=True, timeout=10)
            return r.stdout.strip() if r.returncode == 0 else None
        except (OSError, subprocess.SubprocessError):
            return None

    status = git("status", "--porcelain", "--untracked-files=no")
    return {"commit": git("rev-parse", "HEAD"), "branch": git("rev-parse", "--abbrev-ref", "HEAD"),
            "dirty": None if status is None else bool(status)}


def environment():
    """Our environment variables as set for this run; secrets as "set"."""
    return {k: ("set" if secret(k) else v) for k, v in sorted(os.environ.items())
            if k.startswith(ENV_PREFIXES) and v != ""}


def settings():
    """Every tunable as the modules resolved it (defaults included), not only what the
    environment overrides: two runs with the same values here take the same decisions."""
    from . import actions, agent, economics, memory, play, prose, reader, strategist

    out = {}
    for mod in (actions, agent, economics, memory, play, prose, reader, strategist):
        name = mod.__name__.rsplit(".", 1)[1]
        for k, v in sorted(vars(mod).items()):
            if (k.isupper() and not k.startswith("_") and isinstance(v, SIMPLE) and not secret(k)
                    and len(repr(v)) <= 200):
                out[f"{name}.{k}"] = list(v) if isinstance(v, tuple) else v
    return out


def agent_policy():
    """How the next move is decided, and who may choose it."""
    from . import agent, strategist

    return {"decides": agent.POLICY, "strategist": strategist.ENABLED, "strategist_prompt": strategist.VERSION}


def resolve(kind, cases=(), parallel=None, playbook=None, data_dir=None):
    """The configuration of a run and its fingerprint."""
    from . import memory, reader, reader_cache

    data_dir = Path(data_dir or os.environ.get("ARENA_DATA", "data/package"))
    data_hash, files = tree_sha(data_dir)
    mem = Path(memory.FILE)
    archive = Path(os.environ.get("PEGASUS_READER_ARCHIVE", "data/reader_archive.json"))
    try:
        suppliers = len(json.loads(mem.read_text(encoding="utf-8"))) if mem.is_file() else 0
    except (OSError, ValueError):
        suppliers = None
    env = environment()
    behaviour = {
        "code": code(),
        "settings": settings(),
        "env": {k: v for k, v in env.items() if k not in NOT_BEHAVIOUR},
        "data": {"path": str(data_dir), "sha256": data_hash, "files": files,
                 "release": (data_dir / "release-sunday").is_dir()},
        "memory": {"path": str(mem), "sha256": sha(mem), "suppliers": suppliers},
        "reader": {"enabled": reader.ENABLED, "prompt": reader.VERSION, "archive": str(archive),
                   "archive_sha256": sha(archive), "cache": getattr(reader_cache, "MODE", None)},
        "playbook": {"path": playbook, "sha256": sha(playbook) if playbook else None},
        "policy": agent_policy(),
        "python": platform.python_version(),
    }
    canon = json.dumps(behaviour, sort_keys=True, default=str)
    return {
        "fingerprint": hashlib.sha256(canon.encode()).hexdigest()[:12],
        "run": {"set": kind, "cases": list(cases), "parallel": parallel, "argv": sys.argv[1:],
                "started": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                "validated": os.environ.get("HOLLERAU_VALIDATED") or None,
                "arena": os.environ.get("ARENA_URL") or None, "platform": platform.platform()},
        **behaviour,
        "env_all": env,
    }


def record(kind, cases=(), parallel=None, playbook=None, data_dir=None):
    """Write the configuration before the run starts. Returns (run directory, configuration);
    (None, configuration) if the directory cannot be written - a log is never a reason not to play."""
    cfg = resolve(kind, cases, parallel, playbook, data_dir)
    stamp = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
    out = runs_dir() / f"{stamp}-{kind}-{cfg['fingerprint']}"
    try:
        out.mkdir(parents=True, exist_ok=True)
        (out / "config.json").write_text(json.dumps(cfg, indent=1, sort_keys=True, default=str), encoding="utf-8")
    except OSError as e:
        log.warning("run configuration not written (%s)", e)
        return None, cfg
    return out, cfg


def describe(cfg):
    """One line for the terminal: what is about to play."""
    c = cfg["code"]
    commit = (c.get("commit") or "no-git")[:7] + ("+dirty" if c.get("dirty") else "")
    return (f"run {cfg['fingerprint']}: code {commit}, policy {cfg['policy']['decides']}"
            f"{'+strategist' if cfg['policy']['strategist'] else ''}, data {str(cfg['data']['sha256'])[:8]} "
            f"({cfg['data']['files']} files), memory {cfg['memory']['suppliers']} supplier(s), "
            f"reader {'LLM' if cfg['reader']['enabled'] else 'keywords'}")


class Journal:
    """One JSON line per decision, safe across the parallel cases. Writing never raises."""

    def __init__(self, run_dir, name="decisions.jsonl"):
        self.path = Path(run_dir) / name if run_dir else None
        self.lock = threading.Lock()

    def write(self, **entry):
        if not self.path:
            return
        line = json.dumps({"t": round(time.time(), 3), **entry}, sort_keys=True, default=str)
        try:
            with self.lock, self.path.open("a", encoding="utf-8") as f:
                f.write(line + "\n")
        except OSError as e:
            log.warning("journal not written (%s)", e)


def save(run_dir, name, payload):
    """A JSON file next to the configuration (e.g. results.json); never raises."""
    if not run_dir:
        return
    try:
        (Path(run_dir) / name).write_text(json.dumps(payload, indent=1, sort_keys=True, default=str),
                                          encoding="utf-8")
    except OSError as e:
        log.warning("%s not written (%s)", name, e)

