    case = cases.get(s.get("case_id")); r = s.get("result") or {}
    if not case or not r.get("c_open") or not r.get("c_best"):
        continue
    span = r["c_open"] - r["c_best"]
    if span <= 1:
        continue
    cid = s["case_id"].split(":")[-1]; sessions[cid] += 1
    for e in r.get("trace") or []:
        if e.get("actor") == "buyer":
