        return {"ok": False, "errors": ["decision must be an object with `emails` or `close`"], "diagnostics": [],
                "costs": [], "batch": None}
    emails, close = decision.get("emails") or [], decision.get("close")
    if emails and close:
        errors.append("a decision is either e-mails or a close (accept / walk_away), never both")
    if not emails and not close:
        errors.append("empty decision: give `emails` or `close`")
    batch = {"emails": [], "close": None, "note": str(decision.get("note") or "")[:600]}
    with state.lock:
        seen = set()
        for mail in emails if not close else []:
            if isinstance(mail, dict) and (m := _email(state, mail, seen, errors, diagnostics, costs)):
                batch["emails"].append(m)
        if close and not emails:
            batch["close"] = _close(state, close if isinstance(close, dict) else {}, errors, diagnostics)
        unanswered = [s for s in state.ready() if s not in seen] if emails else []
        if unanswered:
            diagnostics.append(f"no e-mail for {unanswered}: their 60-second clocks keep running; "
                               "a thread left unanswered times out and repeats your last offer")
    ok = not errors
    return {"ok": ok, "errors": errors, "diagnostics": diagnostics, "costs": costs, "batch": batch if ok else None}

toolUseResult.content:
"""What the model wants to send, checked before anything leaves.

`prepare` never rewrites a decision. It returns `errors` (the arena would refuse it, it would
score 0, or it addresses a thread that cannot be answered now: nothing is sent) and
`diagnostics` (facts the model should know before committing - it may keep its choice).
Protocol and mandate are enforced here; tactics are not.
"""

import hashlib
import json
import re

from . import economics

MAX_SUBJECT, MAX_BODY, MAX_SHEETS, MAX_REFS = 300, 8000, 3, 20
ID_RE = re.compile(r"\b(?:idx|quote|sc|qn|po|cost|fc|news|doc|ctr|offer):[A-Za-z0-9_.:@/-]*[A-Za-z0-9]")


def fingerprint(batch):
    return hashlib.sha256(json.dumps(batch, sort_keys=True, default=str).encode()).hexdigest()[:16]


def known_ids(state):
    """IDs a message may cite: the data package, the case's own facts and refs, and the offers
    made in this session."""
    ids = set(state.facts) | set(state.case.get("refs") or [])
    for events in state.threads.values():
        for m in events:
            ids.update(ts["term_sheet_id"] for ts in m.get("term_sheets") or [] if ts.get("term_sheet_id"))
    return ids


def _email(state, mail, seen, errors, diagnostics, costs):
    sid = mail.get("supplier_id")
    where = f"e-mail to {sid}"
    if sid not in state.threads:
        errors.append(f"{where}: unknown supplier; the suppliers of this case are {list(state.threads)}")
        return None
    if sid in seen:
        errors.append(f"{where}: at most one e-mail per supplier in a decision")
        return None
    seen.add(sid)
    if sid not in state.live():
        errors.append(f"{where}: this thread has ended ({state.status(sid)})")
    elif sid in state.inflight:
        errors.append(f"{where}: your previous e-mail is still unanswered - wait for the reply")
    elif state.moves_left(sid) <= 0:
        errors.append(f"{where}: no message left in this thread - you may only accept or walk away")
    subject, body = str(mail.get("subject") or ""), str(mail.get("body") or "")
    if not body.strip():
        errors.append(f"{where}: empty body")
    if len(subject) > MAX_SUBJECT:
        errors.append(f"{where}: subject over {MAX_SUBJECT} characters")
    if len(body) > MAX_BODY:
        errors.append(f"{where}: body over {MAX_BODY} characters")
    sheets = [dict(ts.get("terms", ts)) for ts in mail.get("term_sheets") or []]
    if len(sheets) > MAX_SHEETS:
        errors.append(f"{where}: {len(sheets)} term sheets, at most {MAX_SHEETS}")
    best = state.best_standing()
    movement = economics.movement(state.case, state.threads[sid], state.std.get(sid), state.estimate.get(sid))
    last_ask = (movement.get("our_asks_eur") or [None])[-1]
    evaluated = []
    for n, terms in enumerate(sheets, 1):
        e = state.evaluate(sid, terms)
        for p in e["problems"]:
            errors.append(f"{where}, sheet {n}: {p}")
        evaluated.append(e)
        costs.append({"supplier_id": sid, "sheet": n, "terms": terms, "cost_eur": e["total_eur"],
                      "commercial_eur": e["commercial_eur"], "relationship_eur": e["relationship_eur"],
                      "relationship": e["relationship"]})
        price = terms.get("unit_price")
        if isinstance(price, int | float) and not any(s in body for s in (f"{price:.2f}", f"{price:.2f}".replace(".", ","))):
            diagnostics.append(f"{where}, sheet {n}: the price {price:.2f} is not written in the body; "
                               "only the term sheet binds, but text and sheet should say the same")
        if e["total_eur"] is not None and best and e["total_eur"] > best[0] + 0.005:
            diagnostics.append(
                f"{where}, sheet {n}: it would cost us {e['total_eur']:.2f} EUR, more than a sheet you can accept "
                f"right now ({best[2]} from {best[1]}: {best[0]:.2f} EUR)")
    asks = [e["total_eur"] for e in evaluated if e["total_eur"] is not None]
    if asks and last_ask is not None:
        step = min(asks) - last_ask
        if step > 0.005:
            since = movement.get("supplier_since_our_last_move_eur")
            moved = "unknown" if since is None else f"{since:.2f} EUR"
            diagnostics.append(f"{where}: you concede {step:.2f} EUR against your last ask; "
                               f"the supplier's move since that ask: {moved}")
        elif step < -0.005:
            diagnostics.append(f"{where}: this asks {-step:.2f} EUR more than your last ask (you are taking back a concession)")
    if state.status(sid) == "final_offer":
        diagnostics.append(f"{where}: its last e-mail was marked final_offer - its last word; pushing further may make it walk")
    refs = [str(r) for r in mail.get("refs") or []]
    if len(refs) > MAX_REFS:
        errors.append(f"{where}: {len(refs)} refs, at most {MAX_REFS}")
    known = known_ids(state)
    for ref in sorted(set(refs) | set(ID_RE.findall(body))):
        if ref not in known:
            errors.append(f"{where}: {ref} is not a known data ID - an unknown ID is counted as contradicted and costs trust")
        elif ref not in state.facts and not ref.startswith("offer:"):
            diagnostics.append(f"{where}: {ref} is named by the case but its value is not in our data - "
                               "cite it without a figure, or the figure may be found wrong")
    out = {"supplier_id": sid, "message": {"subject": subject, "body": body, "term_sheets": [{"terms": t} for t in sheets]}}
    if refs:
        out["message"]["refs"] = refs
    return out


def _close(state, close, errors, diagnostics):
    kind = close.get("type")
    alt = economics.alternative(state.case)
    if kind == "walk_away":
        best = state.best_standing()
        if best and (alt is None or best[0] < alt):
            diagnostics.append(f"walking away gives up a signable sheet at {best[0]:.2f} EUR ({best[2]}); "
                               + ("without a deal this case scores 0" if alt is None else f"the alternative costs {alt:.2f} EUR"))
        live = state.live()
        if not live:
            errors.append("no live thread to close")
            return None
        return {"supplier_id": live[0], "message": {"action": {"type": "walk_away"}}}
    if kind != "accept":
        errors.append("close.type must be accept or walk_away")
        return None
    sid, sheet_id = close.get("supplier_id"), close.get("term_sheet_id")
    if sid not in state.threads or sid not in state.live():
        errors.append(f"accept: {sid} is not a live supplier of this case")
        return None
    standing_id, terms = state.standing(sid)
    if sheet_id != standing_id:
        errors.append(f"accept: only the supplier's standing sheet can be accepted, which is {standing_id} for {sid}; "
                      "a package it only describes must first come back as its standing offer")
        return None
    if sid in state.inflight:
        errors.append(f"accept: your e-mail to {sid} is still unanswered and may change its offer - wait for the reply")
    e = state.evaluate(sid, terms)
    if e["must_haves_ok"] is False:
        errors.append("accept: this sheet breaks a must-have - the deal would score 0")
    best = state.best_standing()
    if best and e["total_eur"] is not None and best[0] < e["total_eur"] - 0.005:
        diagnostics.append(f"accept: {best[2]} from {best[1]} is signable and cheaper ({best[0]:.2f} against {e['total_eur']:.2f} EUR)")
    if alt is not None and e["total_eur"] is not None and e["total_eur"] > alt:
        diagnostics.append(f"accept: this deal costs {e['total_eur']:.2f} EUR, more than the alternative without a deal ({alt:.2f} EUR)")
    waiting = sorted(state.inflight - {sid})
    if waiting:
        diagnostics.append(f"accept: replies from {waiting} are still on their way; accepting ends the case for all")
    return {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": sheet_id}},
            "cost_eur": e["total_eur"]}


def prepare(state, decision):
    """{"ok", "errors", "diagnostics", "costs", "batch"}; `batch` is what would be sent, None on errors."""
    errors, diagnostics, costs = [], [], []
    if not isinstance(decision, dict):
        return {"ok": False, "errors": ["decision must be an object with `emails` or `close`"], "diagnostics": [],
                "costs": [], "batch": None}
    emails, close = decision.get("emails") or [], decision.get("close")
    if emails and close:
        errors.append("a decision is either e-mails or a close (accept / walk_away), never both")
    if not emails and not close:
        errors.append("empty decision: give `emails` or `close`")
    batch = {"emails": [], "close": None, "note": str(decision.get("note") or "")[:600]}
    with state.lock:
        seen = set()
        for mail in emails if not close else []:
            if isinstance(mail, dict) and (m := _email(state, mail, seen, errors, diagnostics, costs)):
                batch["emails"].append(m)
        if close and not emails:
            batch["close"] = _close(state, close if isinstance(close, dict) else {}, errors, diagnostics)
        unanswered = [s for s in state.ready() if s not in seen] if emails else []
        if unanswered:
            diagnostics.append(f"no e-mail for {unanswered}: their 60-second clocks keep running; "
                               "a thread left unanswered times out and repeats your last offer")
    ok = not errors
    return {"ok": ok, "errors": errors, "diagnostics": diagnostics, "costs": costs, "batch": batch if ok else None}

input.content:
"""The model's tools, served to DeepSeek Harness over MCP (local Streamable HTTP).

`Desk` holds the open decisions; every tool takes the opaque `decision_id` the coordinator gave
the model for this turn, and the desk derives the case from it - the model never names a case.
`commit_decision` is the only tool with an effect, and even it sends nothing: it hands a
validated, immutable batch to the coordinator, which is the only thing that talks to the arena.
The tool methods are plain Python (tested without MCP); `build_server` only wraps them.
"""

import logging
import secrets
import socket
import threading
import time

from . import economics, validation

log = logging.getLogger("pegasus.dsh")

ATTACHMENT_CHARS = 6000
MAX_ROWS = 50


class Decision:
    """One turn of the model on one case: a lease that is active, committed or expired."""

    def __init__(self, state, budget_s, clock=time.monotonic):
        self.id = "dec-" + secrets.token_hex(6)
        self.state, self.clock = state, clock
        self.deadline = clock() + budget_s
        self.drafts, self.batch, self.status = {}, None, "active"
        self.done = threading.Event()
        self.calls = []  # (tool, seconds since the lease opened): the trace of the turn
        self.opened = clock()

    def seconds_left(self):
        return self.deadline - self.clock()

    def expire(self):
        if self.status == "active":
            self.status = "expired"


class Desk:
    def __init__(self):
        self.lock = threading.Lock()
        self.decisions = {}

    def open(self, state, budget_s):
        d = Decision(state, budget_s)
        with self.lock:
            self.decisions[d.id] = d
        return d

    def _get(self, decision_id, tool):
        d = self.decisions.get(decision_id)
        if d is None:
            return None, {"error": "UNKNOWN_DECISION", "detail": "use the decision_id given in this turn's message"}
        d.calls.append((tool, round(d.clock() - d.opened, 2)))
        return d, None

    def _open(self, decision_id, tool):
        """For tools that prepare or engage: the lease must still be active and in time."""
        d, err = self._get(decision_id, tool)
        if err:
            return None, err
        if d.status == "committed":
            return None, {"error": "DECISION_COMMITTED", "detail": "this turn's decision is already engaged; stop here"}
        if d.status == "expired" or d.seconds_left() <= 0:
            d.expire()
            return None, {"error": "EXPIRED_DECISION", "detail": "this turn's time is over; nothing more can be sent now"}
        return d, None

    # -- read-only tools ------------------------------------------------------------------------
    def get_case_state(self, decision_id):
        d, err = self._get(decision_id, "get_case_state")
        if err:
            return err
        return {**d.state.snapshot(), "seconds_left_in_this_turn": round(d.seconds_left(), 1)}

    def read_thread(self, decision_id, supplier_id):
        d, err = self._get(decision_id, "read_thread")
        if err:
            return err
        events = d.state.threads.get(supplier_id)
        if events is None:
            return {"error": "UNKNOWN_SUPPLIER", "suppliers": list(d.state.threads)}
        out = []
        for m in events:
            item = {"from": "you" if m.get("from") == "buyer" else (m.get("from") or supplier_id),
                    "subject": m.get("subject"), "body": m.get("body"), "term_sheets": m.get("term_sheets") or []}
            if m.get("from") != "buyer":
                item.update(status=m.get("status"), missing_fields=m.get("missing_fields") or [],
                            claim_results=m.get("claim_results") or [], signals=m.get("signals") or {})
                item["attachments"] = [{"name": a.get("name"), "text": (a.get("text") or "")[:ATTACHMENT_CHARS]}
                                       for a in m.get("attachments") or []]
            elif m.get("refs"):
                item["refs"] = m["refs"]
            out.append(item)
        return {"supplier_id": supplier_id, "messages": out}

    def evaluate_offers(self, decision_id, supplier_id, term_sheets):
        d, err = self._get(decision_id, "evaluate_offers")
        if err:
            return err
        if supplier_id not in d.state.threads:
            return {"error": "UNKNOWN_SUPPLIER", "suppliers": list(d.state.threads)}
        out = [d.state.evaluate(supplier_id, dict(ts.get("terms", ts))) for ts in term_sheets or []]
        totals = [e["total_eur"] for e in out if e["total_eur"] is not None]
        return {"supplier_id": supplier_id, "evaluations": out,
                "cheapest_for_us_eur": min(totals) if totals else None,
                "alternative_without_a_deal_eur": economics.alternative(d.state.case)}

    def search_structures(self, decision_id, supplier_id, target_cost_eur, restrict=None, limit=12):
        d, err = self._get(decision_id, "search_structures")
        if err:
            return err
        st = d.state
        if supplier_id not in st.threads:
            return {"error": "UNKNOWN_SUPPLIER", "suppliers": list(st.threads)}
        try:
            target = float(target_cost_eur)
        except (TypeError, ValueError):
            return {"error": "INVALID_TERMS", "detail": "target_cost_eur must be a number of EUR"}
        return {"supplier_id": supplier_id, **economics.structures_for_target(
            st.case, target, st.std.get(supplier_id), st.estimate.get(supplier_id), restrict or None,
            max(1, min(int(limit or 12), 40)))}

    def lookup_facts(self, decision_id, ids):
        d, err = self._get(decision_id, "lookup_facts")
        if err:
            return err
        st, out = d.state, {}
        offers = {ts["term_sheet_id"]: {"supplier": sid, "terms": ts.get("terms")}
                  for sid, events in st.threads.items() for m in events
                  for ts in m.get("term_sheets") or [] if ts.get("term_sheet_id")}
        for ref in (ids or [])[:40]:
            if ref in st.facts:
                out[ref] = st.facts[ref]
            elif ref in offers:
                out[ref] = offers[ref]
            elif ref in (st.case.get("refs") or []):
                out[ref] = {"known": False, "note": "named by the case, value not in our data"}
            else:
                out[ref] = None
        return {"facts": out, "note": "null: not a known ID - do not cite it"}

    def query_data(self, decision_id, sql, limit=20):
        d, err = self._get(decision_id, "query_data")
        if err:
            return err
        if d.state.pkg is None:
            return {"error": "NO_DATA_PACKAGE"}
        try:
            return {"rows": d.state.pkg.query(sql, limit=max(1, min(int(limit or 20), MAX_ROWS)))}
        except Exception as e:  # a bad query is the model's to fix, never a crash of the turn
            return {"error": "QUERY_FAILED", "detail": f"{type(e).__name__}: {e}"[:400]}

    def update_hypotheses(self, decision_id, notes):
        d, err = self._get(decision_id, "update_hypotheses")
        if err:
            return err
        st = d.state
        with st.lock:
            by_id = {h["id"]: h for h in st.hypotheses}
            for n in notes or []:
                if not isinstance(n, dict) or not str(n.get("text") or "").strip():
                    continue
                hid = n.get("id") or f"h{len(st.hypotheses) + 1}"
                note = {"id": hid, "text": str(n["text"])[:500], "status": n.get("status") or "supposed",
                        "sources": [str(s)[:80] for s in n.get("sources") or []][:8]}
                if hid in by_id:
                    by_id[hid].update(note)
                else:
                    st.hypotheses.append(note)
                    by_id[hid] = note
            return {"your_notes": st.hypotheses}

    # -- prepare and engage -----------------------------------------------------------------------
    def prepare_decision(self, decision_id, decision, commit=False):
        d, err = self._open(decision_id, "prepare_decision")
        if err:
            return err
        result = validation.prepare(d.state, decision)
        out = {"ok": result["ok"], "errors": result["errors"], "diagnostics": result["diagnostics"],
               "costs": result["costs"], "seconds_left_in_this_turn": round(d.seconds_left(), 1)}
        if not result["ok"]:
            out["next"] = "fix the errors and prepare again; nothing was sent"
            return out
        draft_id = "draft-" + validation.fingerprint(result["batch"])
        d.drafts[draft_id] = result["batch"]
        out["draft_id"] = draft_id
        if commit:
            return {**out, **self._commit(d, draft_id)}
        out["next"] = "call commit_decision with this draft_id to send it, or prepare a changed decision"
        return out

    def commit_decision(self, decision_id, draft_id):
        d, err = self._open(decision_id, "commit_decision")
        if err:
            return err
        if draft_id not in d.drafts:
            return {"error": "UNKNOWN_DRAFT", "detail": "prepare the decision first; a changed decision needs a new draft"}
        return self._commit(d, draft_id)

    def _commit(self, d, draft_id):
        with d.state.lock:
            # the state may have moved since the draft was prepared: validate what is about to leave
            batch = d.drafts[draft_id]
            stale = [m["supplier_id"] for m in batch["emails"] if m["supplier_id"] not in d.state.ready()]
            if stale:
                return {"error": "STALE_STATE", "detail": f"{stale} can no longer be answered; read the state and prepare again"}
            d.batch, d.status = batch, "committed"
        d.done.set()
        return {"committed": True, "draft_id": draft_id,
                "next": "your decision is engaged and is being sent; end your turn now with one short line"}


def build_server(desk):
    """The MCP server over `desk`. Tool names and descriptions are what the model reads."""
    from mcp.server.mcpserver import MCPServer
    from mcp.types import ToolAnnotations

    mcp = MCPServer("tacto", instructions="A buyer's desk: read the case, compute costs, prepare and engage decisions.")
    ro = ToolAnnotations(readOnlyHint=True)

    @mcp.tool(annotations=ro)
    def get_case_state(decision_id: str) -> dict:
        """The current state of the case: mandate, cost of the alternative, and per supplier its
        standing sheet with what it costs us, its last e-mail, how far each side has moved, the
        seconds and messages left. Already included in each turn's message; call it again only
        to refresh."""
        return desk.get_case_state(decision_id)

    @mcp.tool(annotations=ro)
    def read_thread(decision_id: str, supplier_id: str) -> dict:
        """Every e-mail of one supplier thread in full, both directions, with the text of its
        attachments (quote PDF with its standard terms, cost breakdown, ...)."""
        return desk.read_thread(decision_id, supplier_id)

    @mcp.tool(annotations=ro)
    def evaluate_offers(decision_id: str, supplier_id: str, term_sheets: list[dict]) -> dict:
        """What each term sheet would cost us in EUR, by part, with this supplier's standard terms
        filling what a sheet leaves out. A term sheet is an object with the case's negotiable
        fields, e.g. {"unit_price": 50.25, "payment_days": 60}. Use it for sheets you consider
        sending and to compare the supplier's own sheets. Costs are computed, never guess them."""
        return desk.evaluate_offers(decision_id, supplier_id, term_sheets)

    @mcp.tool(annotations=ro)
    def search_structures(decision_id: str, supplier_id: str, target_cost_eur: float,
                          restrict: dict | None = None, limit: int = 12) -> dict:
        """You choose the total cost you aim at for us (EUR, same unit as cost_eur); this returns,
        for every allowed combination of the non-price terms, the exact unit price that makes it
        cost us that - sorted by price, highest first: at equal cost for us, the supplier prefers
        the higher price. `restrict` narrows the combinations, e.g. {"payment_days": [30, 45]}."""
        return desk.search_structures(decision_id, supplier_id, target_cost_eur, restrict, limit)

    @mcp.tool(annotations=ro)
    def lookup_facts(decision_id: str, ids: list[str]) -> dict:
        """The recorded values of data IDs (idx:, po:, quote:, sc:, cost:, fc:, news:, doc:, ctr:,
        offer:). The arena checks any ID you cite against these values."""
        return desk.lookup_facts(decision_id, ids)

    @mcp.tool(annotations=ro)
    def query_data(decision_id: str, sql: str, limit: int = 20) -> dict:
        """A read-only SQL query on the company's procurement data (orders, quotes, indices,
        scorecards, contracts, news). Start with: SELECT name FROM sqlite_master WHERE type='table'."""
        return desk.query_data(decision_id, sql, limit)

    @mcp.tool()
    def update_hypotheses(decision_id: str, notes: list[dict]) -> dict:
        """Your private notes on this case, kept across turns: what you believe about a supplier,
        what you asked, what remains unknown. Each note: {"id" (to revise one), "text", "status":
        supposed | supported | contradicted | withdrawn, "sources": [...]}. Revise a note when the
        supplier contradicts it."""
        return desk.update_hypotheses(decision_id, notes)

    @mcp.tool()
    def prepare_decision(decision_id: str, decision: dict, commit: bool = False) -> dict:
        """Check a decision before it is sent. `decision` is either
        {"emails": [{"supplier_id", "subject", "body", "term_sheets": [{...}, up to 3], "refs": [data IDs]}], "note": "why"}
        - at most one e-mail per supplier, several suppliers in one decision are sent in parallel -
        or {"close": {"type": "accept", "supplier_id", "term_sheet_id"}} or {"close": {"type": "walk_away"}}.
        Returns errors (must be fixed), diagnostics (facts to weigh; you may keep your choice) and
        the exact cost of every sheet. With commit=true a decision without errors is engaged at
        once; otherwise call commit_decision with the returned draft_id."""
        return desk.prepare_decision(decision_id, decision, commit)

    @mcp.tool()
    def commit_decision(decision_id: str, draft_id: str) -> dict:
        """Engage a prepared decision: it is sent exactly as prepared. One decision per turn."""
        return desk.commit_decision(decision_id, draft_id)

    return mcp


def free_port():
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0))
        return s.getsockname()[1]


class ToolServer:
    """The MCP server on a local port, in a background thread of this process."""

    def __init__(self, desk, port=None):
        import uvicorn

        self.port = port or free_port()
        self.url = f"http://127.0.0.1:{self.port}/mcp"
        app = build_server(desk).streamable_http_app(json_response=True, stateless_http=True)
        self.server = uvicorn.Server(uvicorn.Config(app, host="127.0.0.1", port=self.port, log_level="warning"))
        self.thread = threading.Thread(target=self.server.run, name="tacto-mcp", daemon=True)

    def start(self, timeout=15.0):
