import json, re, os
p = ".claude/projects/-home-animus/422a02e0-ed78-4ce0-93eb-062721198ef6.jsonl"
MASK = re.compile(r"sk-[A-Za-z0-9_\-]{8,}")
keys = set()
for env in ("ehl-tacto/hollerau-agent/.env", "ehl-tacto/hollerau-dsh/.env"):
    try:
        for line in open(env):
            k, sep, v = line.partition("=")
            v = v.strip().strip("\"'")
            if sep and any(t in k for t in ("KEY", "TOKEN", "SECRET")) and len(v) >= 12:
                keys.add(v)
    except OSError:
        pass
lines = open(p).read().splitlines()
print("lignes:", len(lines), "; taille Mo:", round(os.path.getsize(p) / 1e6, 1), "; secrets connus (.env):", len(keys))
goal = None; rows = []
for i, line in enumerate(lines):
    try: o = json.loads(line)
    except Exception: continue
    hit = any(k in line for k in keys) or bool(MASK.search(line))
    moteur = "ehl-moteur-vault" in line
    msg = o.get("message") or {}
    c = msg.get("content")
    text = c if isinstance(c, str) else " ".join(x.get("text", "") for x in c if isinstance(x, dict) and x.get("type") == "text") if isinstance(c, list) else ""
    rows.append((i, o.get("timestamp"), o.get("type"), hit, moteur, text))
    if goal is None and o.get("type") == "user" and "/goal" in text[:300] and "cancel" not in text[:300]:
        goal = i
print("premier message utilisateur contenant /goal : ligne", goal, rows[goal][1] if goal is not None else None)
print("lignes avec un secret :", [r[0] for r in rows if r[3]][:40], "... total", sum(1 for r in rows if r[3]))
print("lignes mentionnant ehl-moteur-vault : total", sum(1 for r in rows if r[4]), "; dernières :", [r[0] for r in rows if r[4]][-12:])
for i, ts, typ, hit, mot, text in rows:
    if typ == "user" and text.strip() and not text.startswith("<") and len(text) < 4000:
        print(i, ts, MASK.sub("sk-[masqué]", text[:110]).replace("\n", " "))
EOF

