    if i >= 343 and "ehl-moteur-vault" in line:
        o = json.loads(line)
        for m in re.finditer(r"ehl-moteur-vault", line):
            ctx = line[max(0, m.start() - 110): m.end() + 60]
            print(f"ligne {i} type={o.get('type')}: …{MASK.sub('[masqué]', ctx)}…")
